11	class RoleSeeder extends Seeder
12	{
13	    /**
14	     * Ruoli baseline (design §7.3, roadmap #4). Il core resta agnostic: lo
15	     * skeleton fornisce questo seed di default, personalizzabile per cliente.
16	     *
17	     * - super-admin: nessun permesso esplicito assegnato, bypassa tutto via
18	     *   Gate::before() (AppServiceProvider).
19	     * - Admin: tutti i permessi generati da shield.
20	     * - Editor: view/create/update su tutte le resource, niente delete.
21	     * - Viewer: solo view/view_any su tutte le resource.
22	     *
23	     * `shield:generate` va comunque rilanciato manualmente dopo ogni resource
24	     * nuova (design §7.7) — qui serve solo a ripopolare la tabella permissions
25	     * dopo un `migrate:fresh`, che la svuota assieme a tutte le altre.
26	     */
27	    public function run(): void
28	    {
29	        Artisan::call('shield:generate', ['--all' => true, '--panel' => 'admin', '--no-interaction' => true]);
30	
31	        app(PermissionRegistrar::class)->forgetCachedPermissions();
32	
33	        Role::firstOrCreate(['name' => 'super-admin', 'guard_name' => 'web']);
34	
35	        $admin = Role::firstOrCreate(['name' => 'Admin', 'guard_name' => 'web']);
36	        $admin->syncPermissions(Permission::where('guard_name', 'web')->get());
37	
38	        $editor = Role::firstOrCreate(['name' => 'Editor', 'guard_name' => 'web']);
39	        $editor->syncPermissions(
40	            Permission::where('guard_name', 'web')
41	                ->where(fn ($query) => $query
42	                    ->where('name', 'like', 'view\_%')
43	                    ->orWhere('name', 'like', 'create\_%')
44	                    ->orWhere('name', 'like', 'update\_%'))
45	                ->get(),
