84	     * Pipeline di estrazione metadati ({@see MetadataExtractionPipeline}, design
85	     * §4.8). Gli estrattori sono risolti dal container nell'ordine dichiarato in
86	     * `config('digital-hub.metadata_extractors')` (ordine = priorità). Il template
87	     * estende/riordina la lista nella config; ogni voce dev'essere un
88	     * {@see MetadataExtractor}.
89	     */
90	    private function registerMetadataExtractionPipeline(): void
91	    {
92	        $this->app->singleton(MetadataExtractionPipeline::class, function (Application $app): MetadataExtractionPipeline {
93	            $extractors = [];
94	            foreach ((array) config('digital-hub.metadata_extractors', []) as $class) {
95	                if (! is_string($class)) {
96	                    continue;
97	                }
98	                $extractor = $app->make($class);
99	                if ($extractor instanceof MetadataExtractor) {
100	                    $extractors[] = $extractor;
101	                }
102	            }
103	
104	            return new MetadataExtractionPipeline($extractors);
