134	    /**
135	     * Alias morph stabili per i modelli del core. Il template forza la morph map
136	     * (Relation::enforceMorphMap) e mappa i propri modelli di dominio, ma non
137	     * conosce quelli del package: il core registra qui i suoi. `morphMap` fa
138	     * merge (non sovrascrive), quindi convive con l'enforce del template a
139	     * prescindere dall'ordine di boot. Serve p.es. alla colonna polimorfica
140	     * `metadata.metadatable_type` (trait HasMetadata su TagGroup/TagCategory).
141	     */
142	    private function registerMorphAliases(): void
143	    {
144	        Relation::morphMap([
145	            'tag_group' => TagGroup::class,
146	            'tag_category' => TagCategory::class,
147	            'tag' => Tag::class,
148	        ]);
