151	    /**
152	     * Pruning degli {@see \AtrioTeam\DigitalHub\Assets\Models\AssetShare}
153	     * scaduti — soprattutto gli share effimeri creati dal download multiplo
154	     * (22e). Usa `model:prune` (Prunable) schedulato, così il template non deve
155	     * configurare nulla. Lo scheduler dev'essere attivo (cron `schedule:run`).
156	     */
157	    private function registerScheduledTasks(): void
158	    {
159	        $this->callAfterResolving(Schedule::class, function (Schedule $schedule): void {
160	            $schedule->command('model:prune', [
161	                '--model' => [AssetShare::class],
162	            ])->hourly();
163	        });
164	    }
165	
166	    /**
167	     * Registra il channel di log dedicato `assets`, su cui scrive la pipeline di
168	     * elaborazione ({@see \AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob}):
169	     * fallimenti best-effort di poster/thumbnail (ffmpeg/Ghostscript) ed errori
170	     * del job. File dedicato così non si perdono nel rumore del log applicativo.
171	     *
172	     * Definito qui (non nel config/logging.php del template) per essere
173	     * self-contained col package; il template può comunque sovrascriverlo
174	     * dichiarando `logging.channels.assets`, nel qual caso questo è un no-op.
175	     */
176	    private function registerAssetsLogChannel(): void
177	    {
178	        if (config('logging.channels.assets') !== null) {
179	            return;
180	        }
181	
182	        config([
183	            'logging.channels.assets' => [
184	                'driver' => 'single',
185	                'path' => storage_path('logs/assets.log'),
186	                // riusa il LOG_LEVEL già risolto in config/logging.php (qui env()
187	                // sarebbe null con config cachata); fallback a debug.
188	                'level' => config('logging.channels.single.level', 'debug'),
189	                'replace_placeholders' => true,
190	            ],
191	        ]);
192	    }
193	}
