1	<?php
2	
3	namespace Database\Seeders;
4	
5	use Illuminate\Database\Seeder;
6	use Illuminate\Support\Facades\Artisan;
7	use Spatie\Permission\Models\Permission;
8	use Spatie\Permission\Models\Role;
9	use Spatie\Permission\PermissionRegistrar;
10	
11	class RoleSeeder extends Seeder
12	{
13	    /**
14	     * Ruoli baseline (design §7.3, roadmap #4). Il core resta agnostic: lo
15	     * skeleton fornisce questo seed di default, personalizzabile per cliente.
16	     *
17	     * - super-admin: nessun permesso esplicito assegnato, bypassa tutto via
18	     *   Gate::before() registrato nativamente da filament-shield
19	     *   (config `super_admin.define_via_gate`, vedi config/filament-shield.php).
20	     * - Admin: tutti i permessi generati da shield.
21	     * - Editor: view/create/update su tutte le resource, niente delete.
22	     * - Viewer: solo view/view_any su tutte le resource.
23	     *
24	     * `shield:generate` va comunque rilanciato manualmente dopo ogni resource
25	     * nuova (design §7.7) — qui serve solo a ripopolare la tabella permissions
26	     * dopo un `migrate:fresh`, che la svuota assieme a tutte le altre.
27	     */
28	    public function run(): void
29	    {
30	        Artisan::call('shield:generate', ['--all' => true, '--panel' => 'admin', '--no-interaction' => true]);
31	
32	        app(PermissionRegistrar::class)->forgetCachedPermissions();
33	
34	        Role::firstOrCreate(['name' => 'super-admin', 'guard_name' => 'web']);
35	
36	        $admin = Role::firstOrCreate(['name' => 'Admin', 'guard_name' => 'web']);
37	        $admin->syncPermissions(Permission::where('guard_name', 'web')->get());
38	
39	        $editor = Role::firstOrCreate(['name' => 'Editor', 'guard_name' => 'web']);
40	        $editor->syncPermissions(
41	            Permission::where('guard_name', 'web')
42	                ->where(fn ($query) => $query
43	                    ->where('name', 'like', 'view\_%')
44	                    ->orWhere('name', 'like', 'create\_%')
45	                    ->orWhere('name', 'like', 'update\_%'))
46	                ->get(),
47	        );
48	
49	        $viewer = Role::firstOrCreate(['name' => 'Viewer', 'guard_name' => 'web']);
50	        $viewer->syncPermissions(
51	            Permission::where('guard_name', 'web')
52	                ->where('name', 'like', 'view\_%')
53	                ->get(),
54	        );
55	    }
56	}
